import json
D={}
def d(slug,desc,steps,pros,cons,alts,tags): D[slug]=dict(description=desc,use_steps=steps,pros=pros,cons=cons,alternatives=alts,tags=tags)

d('chatgpt',"ChatGPT is a conversational assistant from OpenAI. You type a question or instruction and it replies in plain language, which makes it useful for explaining ideas, drafting emails, brainstorming, summarising text and practising a new subject.\n\nIts biggest strength is flexibility: the same chat can help you outline an essay, check a spreadsheet formula and rehearse an interview. Paid plans typically add access to stronger models and extra features such as file uploads and image tools, but what is included changes over time, so check the official plans page. Like every AI assistant it can sound confident while being wrong, so treat answers as a first draft and verify facts, numbers and quotes before using them in schoolwork or at work.",
['Open the website or app and sign in.','Describe the task, your level and the format you want.','Ask follow-up questions, then verify important facts elsewhere.'],['Handles many kinds of tasks in one place','Easy for beginners to start','Mobile, web and desktop apps'],['Can state wrong facts confidently','Usage limits on free access'],['claude','google-gemini','microsoft-copilot'],['assistant','writing','study'])
d('claude',"Claude is an AI assistant made by Anthropic. People often choose it for working with long documents and for careful, readable writing. You can paste or upload a report, ask for a summary, then ask follow-up questions about specific sections.\n\nIt is a good fit for editing drafts, explaining dense material in simpler words and thinking through a problem step by step. As with other assistants, it can make mistakes, so check names, dates and calculations yourself. Features, limits and plans change regularly; the official site shows what your account includes. For sensitive documents, read the privacy information before uploading anything.",
['Sign in on the website or app.','Paste text or attach a document and say what you need.','Refine with follow-up questions and check key facts.'],['Handles long text well','Clear, natural writing style','Good for editing and explaining'],['Free access has usage limits','Can still be wrong on facts'],['chatgpt','google-gemini','perplexity'],['assistant','writing','documents'])
d('google-gemini',"Gemini is Google's AI assistant. Its main appeal is the link with Google services: depending on your account and settings it can work with things like Gmail, Docs, Drive and Search, so you can ask it to summarise a long email thread or help draft a document without copying text between apps.\n\nIt can also take images as input, which helps when you want a photo of a diagram or a worksheet explained. If you already live in a Google account, it is a low-friction place to start. Availability of features varies by country, age and account type, and Google changes plans often, so confirm what you get on the official page. Always double-check factual answers.",
['Open the Gemini site or app with a Google account.','Ask a question or attach a file or image.','Use the share or export options to move results into Docs.'],['Works with the Google ecosystem','Accepts images as input','Free to try'],['Features depend on account and region','Answers need fact-checking'],['chatgpt','claude','microsoft-copilot'],['assistant','google','study'])
d('microsoft-copilot',"Microsoft Copilot is an assistant that appears on the web, in Windows and inside Microsoft 365 apps such as Word, Excel, PowerPoint and Outlook. In those apps it can draft text, summarise long emails, suggest formulas and build a first-draft slide deck from a document.\n\nIt is most useful if your school or workplace already uses Microsoft 365, because it can work with the files you have access to. Which features you see depends on your licence and organisation settings, and some are paid add-ons, so check with your administrator or the official page. As with all AI output, review it before sending or submitting.",
['Open Copilot on the web or inside a Microsoft app.','Describe what you want, or select a document to work on.','Review the result and edit it before sharing.'],['Built into familiar Office apps','Helps with documents, email and slides','Good for workplace use'],['Best features need a paid licence','Output still needs review'],['chatgpt','google-gemini','claude'],['assistant','microsoft','office'])
d('perplexity',"Perplexity works like a search engine that writes a short answer and shows numbered sources next to it. That makes it handy for quick research, because you can click through to the original pages and check what was actually said.\n\nIt is strong for questions where you want recent information and links, and weaker when you need deep reasoning about your own documents. Remember that a cited answer is not automatically correct: read the sources, especially for health, legal or money topics. Plans and limits change, so look at the official page for what the free and paid versions include.",
['Open the site and type your question.','Read the answer and open two or three of the cited sources.','Use follow-up questions to narrow the topic.'],['Shows sources for each answer','Good for current topics','Simple search-like interface'],['Sources can be low quality','Not ideal for creative writing'],['chatgpt','elicit','consensus'],['research','search','sources'])
d('grok',"Grok is the AI assistant from xAI. It is available on the Grok website and apps and is closely tied to the X platform, which means it can talk about what people are discussing there in real time.\n\nThat can be useful for following fast-moving topics, but social posts are noisy and often wrong, so treat anything it says about breaking news carefully and confirm with trusted outlets. Like other assistants it can also help with writing, code and general questions. Access levels and prices have changed several times; check the official site for what is free and what needs a subscription today.",
['Open Grok on the web or in the app.','Ask a question or request a draft.','Check time-sensitive claims against reliable news sources.'],['Awareness of current conversations','General writing and coding help','Web and mobile access'],['Social data can be unreliable','Plan details change often'],['chatgpt','perplexity','claude'],['assistant','news'])
d('deepseek',"DeepSeek is an AI assistant and model family known for strong reasoning and coding results at low cost. You can chat with it on its website and app, and some of its models are published as open weights, which lets developers run them on their own systems.\n\nIt is popular with students and programmers who want step-by-step solutions to maths and code problems. Because the hosted service is operated by a company outside many users' own country, read its privacy policy and avoid entering personal or confidential information. Check the official site for current models and limits.",
['Open the DeepSeek site or app.','Paste a problem and ask for step-by-step reasoning.','Verify the final answer by running the code or checking the maths.'],['Good at reasoning and code','Some models are open weights','Low-cost access'],['Privacy needs careful reading','Features and availability change'],['chatgpt','claude','github-copilot'],['assistant','coding','maths'])
d('grammarly',"Grammarly checks writing as you type and suggests fixes for spelling, grammar, punctuation and clarity. It works in browsers, desktop apps and many text boxes, so you can use it in email, documents and social posts.\n\nBeyond corrections, it can suggest changes in tone and conciseness, and newer versions include generative writing features. It is a safe way to learn from your mistakes if you read each suggestion rather than clicking accept on all of them. Because it reads what you type, check the privacy settings before using it with confidential text. Plans and features change, so see the official pricing page.",
['Install the browser extension or desktop app.','Write as usual and review the underlined suggestions.','Accept only the changes that keep your meaning.'],['Catches many common errors','Works across many apps','Helps you learn patterns'],['Can flatten your personal style','Advanced features are paid'],['quillbot','chatgpt','claude'],['writing','grammar','editing'])
d('quillbot',"QuillBot offers a set of writing tools, mainly a paraphraser, a summariser, a grammar checker and a citation helper. The paraphraser rewrites a sentence in different words and lets you choose how much to change.\n\nStudents use it to simplify heavy text or to find a clearer way to say something. Be careful with academic work: rewording someone else's text without credit is still plagiarism, and many schools have rules about AI assistance. Use it to improve your own writing, not to hide copied material. Check the official site for current limits and plans.",
['Open the paraphraser or summariser.','Paste your own text and pick a mode.','Compare with the original and edit by hand.'],['Several writing tools in one place','Useful for simplifying text','Browser extension available'],['Easy to misuse for plagiarism','Limits on free use'],['grammarly','chatgpt','claude'],['writing','paraphrase','summary'])
d('notion-ai',"Notion AI adds writing and organising help inside the Notion workspace where many people keep notes, tasks and wikis. It can summarise a page, pull out action items, rewrite a paragraph and answer questions about the content you store there.\n\nIts value comes from being where your notes already live: you do not need to copy text into another tool. If you do not use Notion, it offers little. Notion has a free plan, but the AI features depend on your plan and can change, so check the official pricing page before you rely on them. Review any generated summary against the original notes.",
['Open a Notion page and invoke the AI menu.','Choose summarise, action items or write.','Edit the result and keep the original text nearby.'],['Works inside your existing notes','Good for meeting notes and wikis','Saves copy-paste steps'],['Only useful if you use Notion','AI access depends on plan'],['otter-ai','chatgpt','microsoft-copilot'],['notes','productivity'])
d('otter-ai',"Otter records and transcribes meetings, lectures and interviews, then produces searchable notes and a short summary. It can join online meetings, and there is also a phone app for recording in person.\n\nIt saves time when you want to focus on the conversation instead of typing. Accuracy depends on audio quality and accents, so skim the transcript before quoting anyone. Always tell participants when you record and follow your school's or employer's rules and local laws. Free and paid limits change, so confirm on the official page.",
['Connect your calendar or open the app.','Start recording or add the bot to a meeting.','Review the summary and fix names or terms.'],['Searchable transcripts','Summaries and action items','Works for online and in-person'],['Accuracy drops with noise','Recording needs consent'],['fireflies-ai','notion-ai','whisper-openai'],['transcription','meetings'])
d('fireflies-ai',"Fireflies is an AI note taker that joins video calls, records them with permission and creates a transcript, summary and list of action items. It connects with common meeting platforms and can send notes to other tools.\n\nTeams like it because everyone can search past meetings by keyword. Make sure all participants know the meeting is being recorded and check your organisation's rules before using it with confidential topics. Transcripts are rarely perfect, so review key decisions. Plans and limits change, so see the official site for the current free and paid options.",
['Connect your calendar and meeting app.','Let the bot join and record with consent.','Review the summary and share action items.'],['Automatic notes after each call','Search across past meetings','Integrations with other apps'],['Needs everyone to accept recording','Transcript errors happen'],['otter-ai','notion-ai','zapier'],['meetings','transcription'])
d('zapier',"Zapier connects different web apps so they can pass information to each other without code. You build a workflow, called a Zap, from a trigger (for example, a new form response) and one or more actions (add a row to a sheet, send an email, post a message).\n\nIt is useful for small teams and individuals who repeat the same copy-and-paste tasks. Start with one simple automation and test it before relying on it, because a wrong setting can send messages to the wrong people. Task limits and plans change, so check the official pricing page.",
['Create an account and choose a trigger app.','Pick the action you want to happen automatically.','Test the Zap with sample data before turning it on.'],['No programming needed','Thousands of app connections','Saves repetitive work'],['Costs rise with volume','Errors can spread quickly'],['notion-ai','fireflies-ai','chatgpt'],['automation','productivity'])
d('canva',"Canva is a browser-based design tool with templates for presentations, posters, social posts, resumes and videos. You drag elements onto a page, change colours and fonts, and export the result as an image or PDF.\n\nIt also includes AI helpers for things like generating images or rewriting text. It is a good starting point for people without design training because templates handle layout. Some templates, photos and features are limited to paid plans, and licence rules apply to stock content, so check the official terms before using designs commercially.",
['Choose a template for your format.','Replace the text and images with your own.','Download as PDF or PNG.'],['Huge template library','Easy for beginners','Works on web and mobile'],['Many assets need a paid plan','Designs can look generic'],['gamma','figma','adobe-firefly'],['design','poster','presentation'])
d('gamma',"Gamma generates a presentation, document or simple web page from a prompt or an outline. You describe the topic, pick a style, and it builds slides you can edit with a card-based editor.\n\nIt is useful for getting past the blank page quickly. Treat the first version as a draft: check every claim, replace generic text with your own examples and remove slides that do not support your point. Free access and credits change, so look at the official page for the current limits.",
['Enter a topic or paste an outline.','Choose a theme and generate.','Edit each card and export or share.'],['Fast first draft','Clean modern look','Easy sharing as a link'],['Content is often generic','Limits on free use'],['canva','beautiful-ai','chatgpt'],['presentation','slides'])
d('beautiful-ai',"Beautiful.ai is presentation software that keeps slides tidy automatically. When you add or move content, its smart templates adjust spacing and alignment, so you spend less time fixing layout.\n\nIt also includes AI features to draft slides. It suits business presentations where consistency matters. It is a paid product with a free trial that has changed over time, so confirm current terms before you start, and export a backup of your deck.",
['Start from a template or generate a draft.','Add your own content in the smart slides.','Present online or export.'],['Automatic layout','Consistent look','Good for business decks'],['Not a long-term free tool','Less design freedom'],['gamma','canva','chatgpt'],['presentation','business'])
d('figma',"Figma is a collaborative design tool that runs in the browser. Designers use it to create app screens, website layouts, icons and prototypes, and teammates can comment or edit in the same file at the same time.\n\nIt has a learning curve compared with simple graphic tools, but it is the standard for interface design and has a large community of free templates. Students can often find education plans. Features and limits on free plans change, so check the official site.",
['Create a free account and open a new design file.','Draw frames and add components.','Share a link for feedback and use prototype mode to test flows.'],['Real-time collaboration','Industry standard for UI','Large community resources'],['Takes time to learn','Not for photo editing'],['canva','adobe-firefly'],['design','ui','prototype'])
d('midjourney',"Midjourney generates images from text prompts and is known for a distinctive artistic look. It is used for concept art, mood boards, book covers and stylised illustrations.\n\nYou describe the image, review variations and refine by adjusting the prompt or choosing options. Results are strong on style but can struggle with accurate text and anatomy. Check the terms about commercial use and whether your images are public by default. It is a paid service, so see the official site for current plans.",
['Sign in and open the creation interface.','Write a prompt describing subject, style and lighting.','Pick a variation and refine the prompt.'],['Strong artistic quality','Many style options','Active community'],['Paid access','Text in images is unreliable'],['adobe-firefly','leonardo-ai','ideogram'],['image generation','art'])
d('adobe-firefly',"Adobe Firefly is Adobe's family of generative AI tools for creating images, extending photos and applying text effects. Adobe says its models are trained on licensed and public-domain content, which matters to people who worry about copyright.\n\nFirefly also connects with Photoshop and Illustrator, so you can fill or expand an image inside the apps you already use. Usage is measured in credits, and free credits and paid plans change, so check the official page. Always review generated images for errors.",
['Open Firefly on the web or in an Adobe app.','Describe the image or select an area to edit.','Download or continue editing in Photoshop.'],['Integrates with Adobe apps','Focus on commercially safer content','Good editing tools'],['Credits are limited','Adobe account needed'],['midjourney','canva','leonardo-ai'],['image generation','editing'])
d('leonardo-ai',"Leonardo AI is an image generation platform popular with game artists and designers. It offers different models and style presets, plus tools for refining images, creating variations and training small custom styles.\n\nIt is a good choice when you want more control than a single prompt box gives you. Free tokens and plan details change, so check the official site. Review licence terms before commercial use and double-check generated images for flaws.",
['Create an account and choose a model.','Write a prompt and select a style preset.','Refine with variations or editing tools.'],['Many models and presets','Good control options','Free daily allowance has existed'],['Interface can overwhelm beginners','Plan limits change'],['midjourney','ideogram','adobe-firefly'],['image generation','game art'])
d('ideogram',"Ideogram is an AI image generator that is better than many tools at putting readable text into pictures, such as poster titles, logos and signs.\n\nYou write a prompt, choose a style and aspect ratio, and compare results. Text can still contain errors, so zoom in and proofread before publishing. Free and paid options change, so check the official site and read the terms on commercial use.",
['Open the site and write your prompt, including the exact text.','Choose a style and ratio.','Generate and proofread the lettering.'],['Better text rendering','Simple interface','Good for posters and logos'],['Spelling mistakes still happen','Plan limits'],['midjourney','leonardo-ai','canva'],['image generation','poster','text'])
d('remove-bg',"Remove.bg removes the background from a photo automatically in seconds. Upload an image of a person, product or object and download a version with a transparent background.\n\nIt is handy for ID photos, product pictures for online shops and design projects. Complex hair or glass edges may need touch-ups. Free downloads are usually smaller than paid high-resolution ones, and pricing changes, so check the official site.",
['Upload your photo.','Wait for the automatic cut-out.','Download the transparent PNG or add a new background.'],['Very fast','No skills needed','API for developers'],['High resolution needs payment','Fine edges can be rough'],['canva','adobe-firefly'],['photo editing','background'])
d('upscayl',"Upscayl is a free, open-source desktop app that enlarges low-resolution images using AI models running on your own computer. Because it runs locally, your pictures are not uploaded to a server.\n\nIt works best on clean images and can add artefacts to very poor ones. A computer with a decent graphics card makes it faster. Download it only from the official project page and check the licence and release notes.",
['Download from the official page and install.','Select an image and choose a model and scale.','Upscale and compare with the original.'],['Free and open source','Private, works offline','Several models'],['Needs a capable computer','Not magic on very blurry images'],['remove-bg','adobe-firefly'],['image','upscale','open source'])
d('runway',"Runway is a creative suite for AI video. You can generate short clips from text or images, remove backgrounds from video, and use editing tools that normally take hours.\n\nIt is used by filmmakers, marketers and students experimenting with new ideas. Generated clips are short and may show visual glitches, so plan to edit and combine them. Usage is based on credits and plans change, so check the official site and the rules about commercial use.",
['Create an account and choose a generation tool.','Describe the scene or upload a start image.','Download the clip and edit it in your video editor.'],['Powerful video features','Good for experiments','Browser-based'],['Clips are short','Credit costs add up'],['pika','capcut','descript'],['video generation','editing'])
d('pika',"Pika turns text prompts or images into short video clips and offers effects such as adding or transforming objects in a scene. It is popular with social media creators who want eye-catching short clips quickly.\n\nExpect short outputs and occasional visual oddities. Free access, credits and commercial-use rules have changed, so check the official page before using clips in a business. Always review results for artefacts before posting.",
['Sign in and pick text-to-video or image-to-video.','Describe the motion you want.','Download and trim in an editor.'],['Fast and playful','Good for social clips','Simple interface'],['Short clips only','Terms and limits change'],['runway','capcut'],['video generation','social'])
d('capcut',"CapCut is a video editor for phone, desktop and browser that is especially popular for short-form videos. It includes templates, automatic captions, background removal and many effects.\n\nIt suits beginners who want to make a polished clip quickly. Some effects and exports are limited to the paid version, and the app's terms and availability can vary by country, so check the official site. Review auto captions for mistakes before posting.",
['Import clips into a new project.','Trim, add captions and effects.','Export in the size your platform needs.'],['Easy for beginners','Auto captions','Lots of templates'],['Some features paid','Availability varies by region'],['descript','runway','canva'],['video editing','captions'])
d('descript',"Descript lets you edit audio and video by editing a transcript. Delete a word from the text and it disappears from the recording, which makes cutting filler words and mistakes very quick.\n\nIt is popular for podcasts, interviews and talking-head videos. It also offers features such as screen recording and AI voice tools. Transcription is not perfect, so check names. Plans and limits change; see the official site.",
['Import a recording and let it transcribe.','Edit the text to cut or reorder sections.','Export audio or video.'],['Very fast spoken-word editing','Screen recording built in','Good for podcasts'],['Learning curve for video','Free plan limits'],['capcut','audacity','otter-ai'],['video','podcast','editing'])
d('elevenlabs',"ElevenLabs creates natural-sounding AI voices from text and can also clone a voice when you have the right to do so. It is used for narration, audiobooks, videos and accessibility.\n\nUse only voices you have permission to copy and follow the service's rules on consent. Listen to the whole result for mispronunciations. Free allowances and paid plans change, so check the official site and licence terms for commercial use.",
['Paste your script and choose a voice.','Adjust speed and stability settings.','Generate, listen fully and download.'],['Realistic voices','Many languages','API available'],['Voice misuse risks','Credits are limited'],['whisper-openai','descript','audacity'],['voice','text to speech'])
d('whisper-openai',"Whisper is an open-source speech recognition model released by OpenAI. It turns spoken audio into text in many languages and can also translate speech to English.\n\nBecause the code is available, developers can run it on their own computers so audio stays private. It is a command-line or code-based tool, so it is better suited to people comfortable with Python than to beginners, though many apps are built on top of it. Accuracy depends on audio quality.",
['Install it following the project instructions.','Run it on an audio file with your chosen model size.','Proofread the transcript.'],['Free and open source','Works offline','Supports many languages'],['Needs technical setup','Slow on weak computers'],['otter-ai','descript','audacity'],['transcription','open source'])
d('audacity',"Audacity is a free, open-source audio editor for Windows, macOS and Linux. You can record, cut, merge and clean up audio, remove background noise and apply effects.\n\nIt is a classic choice for podcasts and voice-overs, though its interface looks dated. Download it only from the official site to avoid fake installers. It does not use AI to edit for you, but it is reliable and has no cost.",
['Download from the official site and install.','Record or import audio.','Apply noise reduction and export as MP3 or WAV.'],['Completely free','Powerful editing tools','Works offline'],['Interface looks old','No automatic AI editing'],['descript','elevenlabs'],['audio','editing','open source'])
d('github-copilot',"GitHub Copilot suggests code as you type inside editors such as VS Code and JetBrains IDEs. It can complete a line, write a function from a comment and answer questions about your code in a chat panel.\n\nIt speeds up routine work but can propose incorrect or insecure code, so read and test everything. It is a paid product with some education access and free options that have varied, so check the official page for what applies to you.",
['Install the extension in your editor and sign in.','Write a comment describing the function you want.','Review, test and edit the suggestion.'],['Works inside your editor','Speeds up routine code','Chat for explanations'],['Can suggest wrong code','Paid for most users'],['cursor','codeium-windsurf','replit'],['coding','ide'])
d('cursor',"Cursor is a code editor built around AI. It looks like VS Code but adds chat and editing features that can read your project, suggest changes across several files and explain unfamiliar code.\n\nIt is helpful for learning a codebase and for repetitive edits. Review every change it proposes and use version control so you can undo mistakes. It offers a free tier with limits and paid plans; the details change often, so check the official pricing page.",
['Download and open your project folder.','Ask the chat to explain or change a file.','Review the diff before accepting.'],['Understands your project context','Familiar VS Code feel','Multi-file edits'],['Usage limits','Changes need careful review'],['github-copilot','codeium-windsurf','replit'],['coding','editor'])
d('replit',"Replit is an online coding environment: you write, run and share programs from the browser with nothing to install. It supports many languages and includes an AI assistant that can help write or explain code.\n\nIt is excellent for learning and for quickly sharing small projects. For large or sensitive projects, consider hosting and costs carefully. Free options and paid plans change, so check the official site.",
['Create an account and start a new project.','Write code and press run.','Share the link or deploy.'],['No setup needed','Good for beginners','Easy sharing'],['Limits on free resources','Less suited to big projects'],['google-colab','cursor','github-copilot'],['coding','learning'])
d('codeium-windsurf',"Windsurf, from the team behind Codeium, is an AI code editor and assistant. It offers autocomplete and an agent-style chat that can read and edit files in your project.\n\nIt competes with tools like Cursor and Copilot. Features and branding have changed over time, so check the official site for the current product names, free tier and limits. As with any coding assistant, test the results and avoid pasting secrets.",
['Install the editor or plugin.','Open a project and try autocomplete and chat.','Review and test generated code.'],['Free tier has been offered','Project-aware chat','Works in an editor'],['Product and plans change','Code needs review'],['cursor','github-copilot'],['coding','editor'])
d('google-colab',"Google Colab provides free notebooks in the browser where you can run Python code, which makes it popular for data science, machine learning and teaching. Notebooks live in your Google Drive and can be shared like documents.\n\nFree sessions have time and resource limits, and optional paid plans offer more power. It is a great way to learn without installing software. Do not upload private data you are not allowed to share.",
['Open Colab with a Google account.','Create a notebook and run a code cell.','Share or save to Drive.'],['Free to start','No installation','Easy sharing'],['Session limits','Not for long production jobs'],['replit','cursor'],['python','data science','notebook'])
d('notebooklm',"NotebookLM from Google lets you upload your own sources, such as PDFs, notes or web pages, and then ask questions about only that material. Answers include references to the passages used, which makes checking easier.\n\nIt can also create summaries, study guides and audio overviews. It is useful for revising from your own readings, because it is less likely to wander off topic. Still compare important points with the original text. Availability and limits change, so check the official page.",
['Create a notebook and add your sources.','Ask questions or request a study guide.','Check each answer against the cited passage.'],['Grounded in your documents','Citations to sources','Study aids'],['Only as good as your sources','Limits on sources'],['chatgpt','claude','elicit'],['study','research','notes'])
d('quizlet',"Quizlet is a study platform built around flashcards, practice tests and games. You can create your own sets or use sets made by other learners, and the app tracks what you know.\n\nActive recall and repetition make flashcards effective, but community sets can contain errors, so verify them with your textbook. Some modes and AI features are paid, and plans change; see the official site.",
['Create a set of terms and definitions.','Study with flashcards and learn mode.','Take a practice test.'],['Easy to start','Multiple study modes','Mobile apps'],['User sets may be wrong','Some features paid'],['anki','chatgpt','notebooklm'],['flashcards','study'])
d('anki',"Anki is a free, open-source flashcard program built around spaced repetition: cards you find hard come back sooner, and easy ones appear less often. This is one of the most evidence-supported ways to remember facts for the long term.\n\nIt takes some time to learn and the desktop interface is plain, but it is very flexible and has add-ons and shared decks. Medical and language learners use it heavily. Download from the official site; some mobile versions have different pricing.",
['Install Anki and create a deck.','Add cards and study a few minutes every day.','Rate each card honestly to tune the schedule.'],['Strong spaced repetition','Free on desktop','Very customisable'],['Steeper learning curve','Plain design'],['quizlet','notebooklm'],['flashcards','memory','open source'])
d('khan-academy-khanmigo',"Khan Academy offers free lessons, practice and tests across school subjects, from early maths to advanced topics. Khanmigo is its AI tutor, designed to guide students with hints and questions instead of just giving answers.\n\nThe core courses are free. Khanmigo availability and cost can vary by country and account type, so check the official site. It is a good option when you want structured learning with built-in practice.",
['Create a free account and choose a course.','Watch the lesson and do the exercises.','Try the AI tutor where it is available.'],['Free core content','Structured courses','Tutor that guides'],['AI tutor access varies','Not all subjects covered'],['duolingo','wolfram-alpha','chatgpt'],['education','school','tutor'])
d('duolingo',"Duolingo teaches languages through short, game-like lessons on your phone or browser. It tracks streaks, gives points and mixes reading, listening and speaking exercises.\n\nIt is excellent for building a daily habit and learning basic vocabulary, though most learners need extra practice such as conversation to become fluent. It has a free version with ads and paid tiers; check the official site for current features.",
['Pick a language and set a daily goal.','Complete a short lesson each day.','Add real conversation practice.'],['Fun and motivating','Free version available','Short lessons'],['Not enough alone for fluency','Ads or limits on free plan'],['khan-academy-khanmigo','chatgpt'],['languages','learning'])
d('wolfram-alpha',"Wolfram Alpha is a computational knowledge engine. Instead of searching the web, it calculates answers: solve equations, plot functions, convert units, show chemistry data and more.\n\nIt is excellent for checking maths homework steps and for reliable factual data, because results come from curated data and computation. Step-by-step solutions are often part of the paid tier. Its input style can need practice, but it is very accurate on supported topics.",
['Type an equation or question.','Read the result and the extra information.','Use step-by-step options to learn the method.'],['Accurate calculations','Wide subject coverage','Good for checking work'],['Step-by-step is limited on free use','Understanding of natural language is limited'],['chatgpt','khan-academy-khanmigo'],['maths','science','calculator'])
d('elicit',"Elicit helps with literature review. You ask a research question and it finds relevant academic papers, extracts key details such as methods and findings into a table and summarises them.\n\nIt can save hours at the start of a project, but you must still read the papers and check that summaries are accurate. Free and paid features change, so check the official page.",
['Enter your research question.','Review the table of papers.','Open and read the important papers yourself.'],['Speeds up literature search','Structured comparison tables','Academic focus'],['Summaries can miss nuance','Limited free usage'],['consensus','scholarcy','zotero'],['research','papers'])
d('consensus',"Consensus is a search engine for scientific research. You ask a question such as whether a habit affects health, and it shows findings from peer-reviewed papers along with links.\n\nIt is a good way to find evidence quickly, but a single summary line cannot capture a study's limits. Open the papers and check study size and quality. Features and plans change; see the official site.",
['Type a yes/no or research question.','Browse the listed studies.','Open the full papers for details.'],['Evidence-focused','Links to papers','Simple interface'],['Summaries are brief','Some features are paid'],['elicit','scholarcy','perplexity'],['research','science'])
d('scholarcy',"Scholarcy turns long research papers and articles into short summary cards with key points, figures, references and limitations. It also creates flashcards.\n\nIt can speed up skimming a stack of readings, but it does not replace reading. Use it to decide what is worth a careful read. Pricing and limits change, so check the official site.",
['Upload a paper or paste a link.','Read the summary card.','Read the original for details you will cite.'],['Fast skimming','Extracts references','Flashcard export'],['Not a substitute for reading','Limits on free use'],['elicit','consensus','zotero'],['research','summary'])
d('zotero',"Zotero is a free, open-source reference manager. A browser button saves papers and web pages with their details, stores PDFs, and helps you create citations and bibliographies in Word and Google Docs.\n\nIt is trusted by students and researchers, supports many citation styles and works across devices. A limited amount of cloud storage is free; more is paid. Download from the official site.",
['Install Zotero and the browser connector.','Save sources as you read.','Insert citations in your word processor.'],['Free and open source','Many citation styles','Browser saving'],['Free storage is limited','Takes a short time to learn'],['elicit','scholarcy'],['citations','research','open source'])
d('semrush',"Semrush is an online marketing suite best known for SEO. It helps you find keywords, check which sites rank for a topic, audit a website for technical issues and study competitors.\n\nIt is powerful but expensive for hobbyists, and its data is estimated, not exact. A limited free account exists in some regions, and plans change, so check the official page. Use it to guide decisions, then confirm with your own Search Console data.",
['Create an account and enter your domain or topic.','Explore keyword and competitor reports.','Compare with Search Console data.'],['Very broad toolset','Competitor insight','Site audit'],['Costly','Data is estimated'],['ubersuggest','google-search-console'],['seo','keywords'])
d('ubersuggest',"Ubersuggest, from Neil Patel, offers keyword ideas, a site audit and basic backlink information. It is more affordable than big SEO suites and has a limited free option, which suits small sites and beginners.\n\nTreat its volume and difficulty numbers as rough estimates. Pricing and limits change; check the official site.",
['Enter a keyword or your domain.','Review keyword ideas and the audit.','Prioritise topics you can actually write well.'],['Beginner friendly','More affordable','Simple reports'],['Less data depth','Free use is limited'],['semrush','google-search-console'],['seo','keywords'])
d('google-search-console',"Google Search Console is a free tool that shows how your website appears in Google Search. It reports which queries bring visitors, which pages are indexed, mobile and speed issues, and any security or manual action problems.\n\nEvery site owner should set it up. You verify ownership, submit your sitemap and then check the performance and indexing reports regularly. It gives real data from Google, which no third-party estimate can match.",
['Add your site and verify ownership.','Submit your sitemap.','Check Performance and Pages reports weekly.'],['Free and official','Real search data','Finds indexing problems'],['Data is delayed','Not a keyword research tool'],['semrush','ubersuggest'],['seo','analytics','google'])
d('jasper',"Jasper is an AI writing platform aimed at marketing teams. It offers templates for ads, blog posts and emails and lets you save brand voice and style guidance so that content stays consistent across a team.\n\nIt is built for business use and is mostly paid, with trials that have changed over time. Generated copy should always be fact-checked and edited by a person, especially claims about products. Compare with general assistants before paying.",
['Set up your brand voice.','Choose a template and brief.','Edit and fact-check before publishing.'],['Brand voice features','Marketing templates','Team workflows'],['Paid and relatively costly','Generic output without editing'],['chatgpt','claude','grammarly'],['marketing','writing'])
d('resume-worded',"Resume Worded reviews your resume and LinkedIn profile and gives a score with suggestions about wording, impact and formatting. It highlights weak phrases and missing results.\n\nThe free check gives a taste; deeper feedback is paid. Treat scores as hints, not truth, and keep your content honest. Pair it with feedback from a real person who knows your field. Pricing changes, so check the official site.",
['Upload your resume.','Read the score and suggestions.','Rewrite weak bullets with real numbers.'],['Specific, actionable tips','Covers LinkedIn too','Quick feedback'],['Deeper feedback paid','Score is not a guarantee'],['jobscan','chatgpt'],['resume','career'])
d('jobscan',"Jobscan compares your resume with a job description and shows which keywords and skills match or are missing. It also checks formatting issues that can confuse applicant tracking systems.\n\nThis helps you tailor each application, as long as you add only skills you truly have. A few scans are typically free and more need a subscription; check the official page. It is a guide, not a guarantee of an interview.",
['Paste your resume and the job description.','Review missing keywords.','Add them only where they are true.'],['Keyword comparison','ATS formatting tips','Easy to use'],['Limited free scans','Can encourage keyword stuffing'],['resume-worded','chatgpt'],['resume','ats','career'])
d('interview-warmup-google',"Interview Warmup is a free practice tool from Google. You choose a field, see common interview questions, answer them out loud and get a transcript with insights, for example about the topics you mentioned and how long you spoke.\n\nIt is useful for building comfort speaking about yourself. It is practice, not a prediction of how a real interviewer will judge you. Combine it with your own notes and a friend's feedback.",
['Open the tool and pick a role area.','Answer questions by voice.','Review the transcript and improve.'],['Free','Low pressure practice','Instant transcript'],['Limited role coverage','Generic feedback'],['chatgpt','jobscan'],['interview','career'])

T=json.load(open('content/seed-tools.json'))
miss=[x['slug'] for x in T if x['slug'] not in D]
extra=[k for k in D if k not in {x['slug'] for x in T}]
print('missing',miss,'extra',extra)
# pricing types: conservative general types, to be re-verified by the owner
PRICE={'notion-ai':'Freemium','beautiful-ai':'Free trial','jasper':'Free trial','semrush':'Paid','cursor':'Freemium','codeium-windsurf':'Freemium','grok':'Freemium','pika':'Freemium','github-copilot':'Paid','midjourney':'Paid','descript':'Freemium','khan-academy-khanmigo':'Freemium','resume-worded':'Freemium','jobscan':'Freemium'}
for x in T:
    c=D.get(x['slug'])
    if c: x.update(c)
    if x['slug'] in PRICE: x['pricing']=PRICE[x['slug']]
    x['last_checked']=None
    assert 'EDIT THIS' not in x['description']
    wc=len(x['description'].split())
    if wc<100: print('short',x['slug'],wc)
json.dump(T,open('content/seed-tools.json','w'),indent=1,ensure_ascii=False)
print(len(T),'tools updated; avg words',sum(len(x['description'].split()) for x in T)//len(T))
